<template><form @submit.prevent="submit" class="space-y-5"><div class="card grid gap-4 md:grid-cols-2"><div class="md:col-span-2"><label>Recipe name *</label><input v-model="draft.title" required maxlength="160"/></div><div class="md:col-span-2"><label>Description / family story</label><textarea v-model="draft.description" rows="3" maxlength="3000"/></div><div><label>Category</label><select v-model="draft.category"><option v-for="c in categories" :key="c">{{c}}</option></select></div><div><label>Visibility</label><select v-model="draft.visibility"><option value="private">Private</option><option value="friends">Friends (available in Phase 2)</option><option value="public">Public (available in Phase 2)</option></select><p class="text-xs text-stone-500 mt-1">Only you can access recipes in Phase 1.</p></div><div><label>Servings</label><input v-model.number="draft.servings" type="number" min="1" max="1000" required/></div><div><label>Preparation (minutes)</label><input v-model.number="draft.prep_minutes" type="number" min="0" required/></div><div><label>Cooking (minutes)</label><input v-model.number="draft.cook_minutes" type="number" min="0" required/></div><div><label>Cover photo (JPG, PNG or WebP; max 5MB)</label><input type="file" accept="image/jpeg,image/png,image/webp" @change="fileChanged"/></div></div>
<div class="card space-y-3"><div class="flex justify-between items-center"><h2 class="text-xl font-bold">Ingredients</h2><button type="button" class="btn btn-secondary" @click="addIngredient">+ Ingredient</button></div><div v-for="(ingredient,index) in draft.ingredients" :key="index" class="grid grid-cols-12 gap-2 items-end"><div class="col-span-3 sm:col-span-2"><label>Qty</label><input v-model.number="ingredient.quantity" type="number" step="any" min="0"/></div><div class="col-span-3 sm:col-span-2"><label>Unit</label><input v-model="ingredient.unit" placeholder="g" maxlength="30"/></div><div class="col-span-5 sm:col-span-7"><label>Ingredient</label><input v-model="ingredient.name" placeholder="Flour" maxlength="200"/></div><button type="button" aria-label="Remove ingredient" class="text-red-800 pb-3" @click="draft.ingredients.splice(index,1)">✕</button></div></div>
<div class="card space-y-3"><div class="flex justify-between items-center"><h2 class="text-xl font-bold">Instructions</h2><button type="button" class="btn btn-secondary" @click="addStep">+ Step</button></div><div v-for="(step,index) in draft.steps" :key="index" class="flex gap-3 items-start"><span class="pt-3 font-bold">{{index+1}}.</span><textarea v-model="step.instruction" rows="2" maxlength="5000" placeholder="Describe this step"/><button type="button" aria-label="Remove step" class="text-red-800 pt-3" @click="draft.steps.splice(index,1)">✕</button></div></div>
<p v-if="error" class="error" role="alert">{{error}}</p><button class="btn" :disabled="busy">{{busy?'Saving…':'Save Recipe'}}</button></form></template>
<script setup lang="ts">
import type {RecipeDraft,Ingredient,Step} from '~/types/recipe'
const props=defineProps<{initial?:RecipeDraft;recipeId?:string}>();const emit=defineEmits<{saved:[id:string]}>()
const categories=['Breakfast','Lunch','Dinner','Dessert','Baking','Snacks','Drinks','Other']
const blank=():RecipeDraft=>({title:'',description:'',category:'Dinner',servings:4,prep_minutes:0,cook_minutes:0,visibility:'private',ingredients:[{position:0,quantity:null,unit:'',name:'',notes:''}],steps:[{position:0,instruction:''}]})
const draft=reactive<RecipeDraft>(props.initial?structuredClone(props.initial):blank());const selectedFile=ref<File|null>(null),busy=ref(false),error=ref('');const repo=useRecipeRepository()
function addIngredient(){draft.ingredients.push({position:draft.ingredients.length,quantity:null,unit:'',name:'',notes:''})}
function addStep(){draft.steps.push({position:draft.steps.length,instruction:''})}
function fileChanged(e:Event){selectedFile.value=(e.target as HTMLInputElement).files?.[0]||null}
async function submit(){busy.value=true;error.value='';try{
 const normalized={...draft,ingredients:draft.ingredients.map((x,i)=>({...x,position:i})),steps:draft.steps.map((x,i)=>({...x,position:i}))}
 const id=await repo.save(normalized,props.recipeId);if(selectedFile.value)await repo.uploadCover(id,selectedFile.value);emit('saved',id)
 }catch(e:any){error.value=e.message||'Unable to save recipe'}finally{busy.value=false}}
</script>
